import 'package:flutter/services.dart'; class InstalledApp { final String name; final String packageName; final String version; final bool isSystemApp; const InstalledApp({ required this.name, required this.packageName, required this.version, required this.isSystemApp, }); factory InstalledApp.fromMap(Map<Object?, Object?> map) { return InstalledApp( name: map['name']?.toString() ?? 'غير معروف', packageName: map['packageName']?.toString() ?? '', version: map['version']?.toString() ?? 'غير معروف', isSystemApp: map['isSystemApp'] == true, ); } } class InstalledAppsService { static const MethodChannel _channel = MethodChannel('com.nathr.security/apps'); Future<List<InstalledApp>> getInstalledApps() async { final result = await _channel.invokeMethod<List<dynamic>>( 'getInstalledApps', ); if (result == null) { return <InstalledApp>[]; } return result.map((item) { if (item is Map<Object?, Object?>) { return InstalledApp.fromMap(item); } throw const FormatException( 'تعذر قراءة بيانات أحد التطبيقات', ); }).toList(); } } 